function setStatus(id: number, status: 'fulfilled' | 'deleted'): ListingRow | undefined {
  const db = getDb();
  const listing = getListingById(id);
  if (!listing) {
    db.update(listings).set({ status, updatedAt: now() }).where(eq(listings.id, id)).run();
    return getListingById(id);
  }
  const currentStatus = listing.status;
  const transitionRows: Record<string, string[]> = {
    active: ['fulfilled', 'deleted'],
    fulfilled: ['deleted'],
  };
  const allowed = transitionRows[currentStatus] ?? [];
  if (!allowed.includes(status)) {
    throw new Error(
      `Cannot transition listing #${id} from "${currentStatus}" to "${status}".`,
    );
  }
  db.update(listings).set({ status, updatedAt: now() }).where(eq(listings.id, id)).run();
  return getListingById(id);
}

