describe('search and status transitions', () => {
  it('searches active listings and excludes non-matching statuses', () => {
    seedServer();
    const { listing } = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    expect(searchListings('200', 'black lotus', undefined, undefined, 1)).toHaveLength(1);
    expect(countSearchResults('200', 'black lotus', undefined, undefined)).toBe(1);

    fulfillListing(listing.id);
    expect(searchListings('200', 'black lotus', undefined, undefined, 1)).toHaveLength(0);
    expect(countSearchResults('200', 'black lotus', undefined, undefined)).toBe(0);

    softDeleteListing(listing.id);
    expect(searchListings('200', 'black lotus', undefined, undefined, 1)).toHaveLength(0);
  });

  it('status transition matrix: legal transitions', () => {
    seedServer();
    const { listing } = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });

    // active -> fulfilled
    expect(() => fulfillListing(listing.id)).not.toThrow();
    expect(listing.status).toBe('fulfilled');

    // re-seed for next test since listing status changed
    seedServer();
    const { listing: listing2 } = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });

    // active -> deleted
    expect(() => softDeleteListing(listing2.id)).not.toThrow();
    expect(listing2.status).toBe('deleted');

    // re-seed for next test
    seedServer();
    const { listing: listing3 } = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });

    // fulfilled -> deleted
    fulfillListing(listing3.id);
    expect(() => softDeleteListing(listing3.id)).not.toThrow();
    expect(listing3.status).toBe('deleted');
  });

  it('status transition matrix: forbidden transitions throw and leave status unchanged', () => {
    seedServer();
    const { listing } = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });

    // re-fulfilling already-fulfilled listing
    fulfillListing(listing.id);
    expect(() => fulfillListing(listing.id)).toThrow('cannot transition from');
    const after1 = getListingById(listing.id);
    expect(after1?.status).toBe('fulfilled');

    // re-deleting already-deleted listing
    seedServer();
    const { listing: listing2 } = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    softDeleteListing(listing2.id);
    expect(() => softDeleteListing(listing2.id)).toThrow('cannot transition from');
    const after2 = getListingById(listing2.id);
    expect(after2?.status).toBe('deleted');

    // fulfilling a 'deleted' listing
    seedServer();
    const { listing: listing3 } = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    softDeleteListing(listing3.id);
    expect(() => fulfillListing(listing3.id)).toThrow('cannot transition from');
    const after3 = getListingById(listing3.id);
    expect(after3?.status).toBe('deleted');

    // fulfilling or deleting an 'expired' listing
    seedServer();
    const { listing: listing4 } = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    fulfillListing(listing4.id);
    const past = Date.now() - 31 * 24 * 3600 * 1000; // past 30-day TTL
    db.update(listings).set({ status: 'expired', expiresAt: past, updatedAt: past }).where(eq(listings.id, listing4.id)).run();
    expect(() => fulfillListing(listing4.id)).toThrow('cannot transition from');
    const after4 = getListingById(listing4.id);
    expect(after4?.status).toBe('expired');

    // deleting an 'expired' listing
    seedServer();
    const { listing: listing5 } = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    softDeleteListing(listing5.id);
    const past2 = Date.now() - 31 * 24 * 3600 * 1000;
    db.update(listings).set({ status: 'expired', expiresAt: past2, updatedAt: past2 }).where(eq(listings.id, listing5.id)).run();
    expect(() => softDeleteListing(listing5.id)).toThrow('cannot transition from');
    const after5 = getListingById(listing5.id);
    expect(after5?.status).toBe('expired');
  });
});

  it('filters search by intent', () => {
    seedServer();
